def read(rel, sig=False):
    return (ROOT/rel).read_text(encoding="utf-8-sig" if sig else "utf-8")
def write(rel, text, sig=False):
    (ROOT/rel).write_text(text,encoding="utf-8-sig" if sig else "utf-8",newline="")
def replace_once(rel, old, new, sig=False):
    s=read(rel,sig)
    if old not in s:
        raise RuntimeError(f"{rel}: expected text not found: {old[:100]!r}")
    s=s.replace(old,new,1)
    write(rel,s,sig)
